import React, { useMemo } from 'react';
import {
    LineChart,
    Line,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    Legend,
    ResponsiveContainer,
} from 'recharts';
import { useForecastData } from './useForecastData';
import { BEACHES } from './Beaches';

const ForecastChart = ({ selectedBeach, data }) => {
    // Get beach coordinates for API call
    const beach = useMemo(() => 
        BEACHES.find(b => b.name === selectedBeach),
        [selectedBeach]
    );

    const lat = beach?.lat || 32.87;
    const lon = beach?.lon || -117.26;

    // Fetch real forecast data from Open-Meteo
    const { forecastData: apiData, loading, error } = useForecastData(lat, lon);

    // Generate 48-hour forecast data (fallback if API fails)
    const fallbackData = useMemo(() => {
        const now = new Date();
        const currentHour = now.getHours();
        const forecast = [];

        // Simulate 48-hour forecast
        for (let i = 0; i < 48; i++) {
            const hour = (currentHour + i) % 24;
            const isTonight = i < (24 - currentHour);
            const dayLabel = isTonight ? 'Today' : 'Tomorrow';

            // Simulate wave height (feet) - ranges 2-8 ft typically
            const baseHeight = 4 + Math.sin((hour - 6) * Math.PI / 12) * 2;
            const swellHeight = baseHeight + Math.random() * 0.5;

            // Wind speed (knots) - typically 5-20 knots
            const windKnots = 12 + Math.sin((hour - 10) * Math.PI / 12) * 6 + Math.random() * 2;

            // Water temp (Celsius) - San Diego 16-22C typically
            const waterTemp = 18 + Math.sin((hour - 12) * Math.PI / 12) * 2;

            // Period (seconds) - typically 8-14s
            const period = 10 + Math.sin((hour - 8) * Math.PI / 12) * 2;

            const timeStr = `${(hour % 12 || 12).toString().padStart(2, '0')}:00 ${hour < 12 ? 'AM' : 'PM'}`;

            forecast.push({
                time: timeStr,
                shortTime: `${hour}h`,
                swellHeight: Math.round(swellHeight * 10) / 10,
                wind: Math.round(windKnots),
                waterTemp: Math.round(waterTemp * 10) / 10,
                period: Math.round(period * 10) / 10,
                hour: i,
                day: dayLabel,
            });
        }

        return forecast;
    }, []);

    // Use real API data if available, otherwise fallback to simulated data
    const forecastData = apiData || fallbackData;

    // Tooltip for detailed info
    const CustomTooltip = ({ active, payload }) => {
        if (!active || !payload || !payload[0]) return null;

        const data = payload[0].payload;
        return (
            <div style={{
                backgroundColor: '#111827',
                border: '1px solid #374151',
                borderRadius: '4px',
                padding: '8px',
                color: '#fff',
                fontSize: '12px',
            }}>
                <div className='containerDetail color-yellow'>
                    {data.time}
                </div>
                <div className='containerDetail flexContainer'>
                    <div className='flex2Column contentRight' style={{ color: '#42a5f5' }}>
                        🌊 Wave Height:
                    </div>  
                    <div className='flexColumn pl-5 contentLeft'>
                    {data.swellHeight} ft
                    </div>
                </div>
                <div className='containerDetail flexContainer'>
                    <div className='flex2Column contentRight' style={{ color: '#ff7043' }}>
                        💨 Wind: 
                    </div>  
                    <div className='flexColumn pl-5 contentLeft'>                        
                        {Math.round(data.wind * 1.15078)} mph
                    </div>
                </div>
                <div className='containerDetail flexContainer'>
                    <div className='flex2Column contentRight' style={{ color: '#26a69a' }}>
                        🌡️ Water Temp: 
                    </div>  
                    <div className='flexColumn pl-5 contentLeft'>
                        {Math.round((data.waterTemp * 9/5) + 32)}°F
                    </div>
                </div>
                <div className='containerDetail flexContainer'>
                    <div className='flex2Column contentRight' style={{ color: '#ab47bc' }}>
                        ⏱️ Period:
                    </div>  
                    <div className='flexColumn pl-5 contentLeft'>
                        {data.period}s
                    </div>
                </div>
            </div>
        );
    };

    return (
        <div className='containerDetail'>
            <div className='containerDetail color-yellow contentLeft size20 p-15 mb-10'>
                📊 48-Hour Forecast {selectedBeach && `@ ${selectedBeach}`}
                {loading && <span style={{ fontSize: '12px', marginLeft: '10px', color: '#666' }}>⏳ Loading real forecast...</span>}
                {error && <span style={{ fontSize: '12px', marginLeft: '10px', color: '#f44336' }}>⚠️ Using simulated data</span>}
            </div>

            {loading && !apiData ? (
                <div style={{
                    textAlign: 'center',
                    padding: '40px',
                    color: '#999',
                    fontSize: '14px',
                }}>
                    Fetching forecast from Open-Meteo...
                </div>
            ) : (
                <>
                    <ResponsiveContainer width="100%" height={300}>
                <LineChart data={forecastData} margin={{ top: 5, right: 20, left: -15, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#ddd" />
                    <XAxis
                        dataKey="shortTime"
                        tick={{ fontSize: 11 }}
                        interval={3}
                        angle={-45}
                        textAnchor="end"
                        height={60}
                    />
                    <YAxis
                        yAxisId="left"
                        domain={[0, (dataMax) => Math.ceil((dataMax || 0) * 1.15)]}
                        label={{ value: '🌊Swell (ft) / ⏱️ Period (s)', angle: -90, position: 'insideLeft' }}
                        tick={{ fontSize: 11 }}
                    />
                    <YAxis
                        yAxisId="right"
                        orientation="right"
                        label={{ value: '💨 Wind (mph)', angle: 90, position: 'insideRight' }}
                        tick={{ fontSize: 11 }}
                    />
                    <YAxis
                        yAxisId="temp"
                        hide={true}
                    />
                    <Tooltip content={<CustomTooltip />} />
                    <Legend />
                    <Line
                        yAxisId="left"
                        type="monotone"
                        dataKey="swellHeight"
                        name="🌊 Swell Height"
                        stroke="#42a5f5"
                        dot={false}
                        strokeWidth={2}
                    />
                    <Line
                        yAxisId="right"
                        type="monotone"
                        dataKey="wind"
                        name="💨 Wind Speed"
                        stroke="#ff7043"
                        dot={false}
                        strokeWidth={2}
                        //strokeDasharray="5 5"
                    />
                    <Line
                        yAxisId="temp"
                        type="monotone"
                        dataKey="waterTemp"
                        name="🌡️ Water Temp"
                        stroke="#26a69a"
                        dot={false}
                        strokeWidth={2}
                        //strokeDasharray="2 4"
                    />
                    <Line
                        yAxisId="left"
                        type="monotone"
                        dataKey="period"
                        name="⏱️ Wave Period"
                        stroke="#ab47bc"
                        dot={false}
                        strokeWidth={2}
                        //strokeDasharray="1 6"
                    />
                </LineChart>
                    </ResponsiveContainer>

                    <div 
                        style={{
                            display: 'grid',
                            gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))',
                            gap: '10px',
                            marginTop: '15px',
                        }}
                        className='containerDetail flexContainer'
                    >
                        {/* Summary stats */}
                        {[
                    {
                        label: '🌊 Best Swell',
                        value: `${Math.max(...forecastData.map(d => d.swellHeight))} ft`,
                        color: '#42a5f5',
                    },
                    {
                        label: '💨 Avg Wind',
                        value: `${Math.round((forecastData.reduce((sum, d) => sum + d.wind, 0)*1.15078) / forecastData.length)} mph`,
                        color: '#ff7043',
                    },
                    {
                        label: '🌡️ Water Temp',
                        value: `${((forecastData[0].waterTemp * 9/5) + 32).toFixed(0)}°F`,
                        color: '#26a69a',
                    },
                    {
                        label: '⏱️ Period',
                        value: `${forecastData[0].period}s`,
                        color: '#ab47bc',
                    },
                        ].map((stat, i) => (
                            <div
                                key={i}
                                style={{
                                    backgroundColor: '#222',
                                    border: `2px solid ${stat.color}`,
                                    borderRadius: '6px',
                                    textAlign: 'center',
                                    fontSize: '12px',
                                }}
                                className='flex4Column'
                            >
                                <div className='containerDetail color-yellow contentLeft size15 mb-5'>{stat.label}</div>
                                <div style={{ fontSize: '16px', fontWeight: 'bold', color: stat.color }}>
                                    {stat.value}
                                </div>
                            </div>
                        ))}
                    </div>
                </>
            )}
        </div>
    );
};

export default ForecastChart;
